 q=frozen();assert read(E/'results/preparation.json')['passed'];assert not(E/'configs/model_selection_frozen.json').exists();pairs=read(E/'data/public/pairs.json');z=dict(np.load(E/'data/public/inputs.npz'));t=dict(np.load(E/'data/_private/targets.npz'));train=np.array([i for i,r in enumerate(pairs)if r['split']=='train']);tune=np.array([i for i,r in enumerate(pairs)if r['dev_role']=='tune']);cohorts={'old96':np.array([i for i in train if pairs[i]['source']=='old']),'aug132':train};assert [len(cohorts[n])for n in q['cohorts']]==[96,132]and len(tune)==21
