 rootlist=sorted({pairs[i]['root_id']for i in tune});tuneroot=torch.tensor([rootlist.index(pairs[i]['root_id'])for i in tune],device='cuda');save(E/'configs/runtime.json',{'created_utc':now(),'torch':torch.__version__,'python':platform.python_version(),'cuda':torch.version.cuda,'device':torch.cuda.get_device_name(),'total_vram_bytes':torch.cuda.get_device_properties(0).total_memory,'pid':os.getpid(),'single_gpu_sequential':True});allruns=[];start=time.perf_counter()
